#!/usr/bin/env python3
# YONPORTFOY_SOR_KALDIR_V1 — "Portföye sor" (paralel haiku asistan) kaldırıldı. Karar: tek asistan = CEO;
# müdür soruları üstteki CEO Assistant sekmesinde sorar. Server ucu + shell'deki kutu silindi.
# Idempotent + .bak + node --check + rollback. TEK build.
# KULLANIM: /opt/krb-assessment/ icine koy →
#   cd /opt/krb-assessment && python3 patch_sor_kaldir.py \
#     && docker build -t krb-assessment:secure . && docker compose up -d --force-recreate krb-assessment
import sys, subprocess, shutil, os, base64
SV='/opt/krb-assessment/server_container.mjs'
SHELLD="/opt/krb-assessment/shells/manager_portfoyum.html"
SOR='    if (method === "POST" && path === "/api/saha/manager-portfoyum/sor") {  /* YONPORTFOY_SOR_V1 */\n      const session = await requireSahaAccess(request, ["manager", "admin"]);\n      let body = {};\n      try { body = await readJson(request); } catch (e) { body = {}; }\n      const soru = (body.soru == null ? "" : String(body.soru)).trim().slice(0, 2000);\n      if (!soru) { sendJson(response, 400, { error: "Soru bos." }); return; }\n      const baglam = (body.baglam == null ? "" : String(body.baglam)).slice(0, 9000);\n      const donem  = (body.donem == null ? "12ay" : String(body.donem)).slice(0, 12);\n      const gecmis = Array.isArray(body.gecmis) ? body.gecmis.slice(-6) : [];\n      if (!process.env.ANTHROPIC_API_KEY) { sendJson(response, 200, { cevap: "AI su an yapilandirilmamis." }); return; }\n      const SYS = "Sen \'Yonetici Portfoy\' ekraninin asistanisin - bir satis yoneticisiyle konusuyorsun. SADECE sana verilen BAGLAM verisinden konus; SAYI ve ISIM UYDURMA. Baglamda olmayan bir seyi sorarsa \'bu ekranda o veri yok - ilgili karta/satira/hucreye tikla\' de. Kisa ve net (2-6 cumle), duz Turkce, urun dili (varyans/kaldirac/lens gibi ic jargon kullanma), suclayici ya da vaatkar degil. Bir rakam verirken donemini belirt (secili donem: " + donem + "). Uygunsa tek somut sonraki adim oner (kimi tasi, kime dokun, kime kampanya).";\n      const msgs = [];\n      msgs.push({ role: "user", content: "BAGLAM (yonetici portfoy - donem " + donem + "):\\n" + (baglam || "(baglam verilmedi)") });\n      msgs.push({ role: "assistant", content: "Baglami aldim, sorunu bekliyorum." });\n      for (const g of gecmis) { if (g && g.rol && g.metin) msgs.push({ role: g.rol === "user" ? "user" : "assistant", content: String(g.metin).slice(0, 1500) }); }\n      msgs.push({ role: "user", content: soru });\n      let cevap = "";\n      try {\n        const m = await anthropic.messages.create({ model: "claude-haiku-4-5-20251001", max_tokens: 700, system: SYS, messages: msgs });\n        cevap = (m.content || []).map(function (c) { return c.text || ""; }).join("").trim();\n      } catch (e) { sendJson(response, 502, { error: "Asistan yanit veremedi." }); return; }\n      if (!cevap) cevap = "Su an bir yanit uretemedim, tekrar dener misin?";\n      try {\n        await query("INSERT INTO saha_sinyal (tenant_id,tip,onem,ozet,detay,kaynak_tip,rep_id,musteri_id,ham_metin) VALUES ($1,\'soru\',1,$2,$3::jsonb,\'yonportfoy_sor\',$4,NULL,$5)",\n          [session.tenantId, soru.slice(0, 300), JSON.stringify({ ekran: "yonetici-portfoy", donem: donem, soru: soru, cevap: cevap.slice(0, 1500) }), session.userId, soru]);\n      } catch (e) { try { console.error("[yonportfoy/sor]", e && e.message); } catch (er) {} }\n      sendJson(response, 200, { cevap: cevap });\n      return;\n    }\n\n'
